expect.proto:
syntax = "proto3";

package example.v1;

import "google/protobuf/struct.proto";

// Base schema carrying the shared identifier.
message Base {
    // The unique identifier.
    int64 id = 1;
}

// A postal address.
message Address {
    // Arbitrary float coordinates keyed by name.
    map<string, double> geo = 1;
    // The street name.
    string street = 2;
    // The ZIP code.
    string zip_code = 3;
}

// A person in the address book.
message Person {
    // The home address.
    Address address = 1;
    // The age in years.
    int64 age = 2;
    // Known email addresses.
    repeated string emails = 3;
    // The unique identifier.
    int64 id = 4;
    // The full name.
    string name = 5;
}

// A schema with a union attribute.
message UnionS {
    // An int or a str.
    google.protobuf.Value val = 1;
}
